mapper.select:
SELECT content_id, title, type, author_id, author_name, create_time, cover FROM (
-- 查询文章表 SELECT p.id as content_id, p.title as title, 0 as type, p.author_id as author_id, ui.user_name as author_name, p.create_time as create_time, p.image as cover FROM posts p LEFT JOIN user_info ui ON p.author_id = ui.user_id WHERE p.status = 1
AND p.title LIKE CONCAT('%', #{title}, '%')
AND p.create_time >= #{startTime}
AND p.create_time <= #{endTime}
AND ui.user_name LIKE CONCAT('%', #{author}, '%')
-- 查询分享表 SELECT s.id as content_id, s.brief as title, 1 as type, s.author_id as author_id, ui.user_name as author_name, s.create_time as create_time, s.image as cover FROM share s LEFT JOIN user_info ui ON s.author_id = ui.user_id WHERE s.status = 1
AND s.brief LIKE CONCAT('%', #{title}, '%')
AND s.create_time >= #{startTime}
AND s.create_time <= #{endTime}
AND ui.user_name LIKE CONCAT('%', #{author}, '%')
-- 查询所有待审核内容(文章和分享) SELECT p.id as content_id, p.title as title, 0 as type, p.author_id as author_id, ui.user_name as author_name, p.create_time as create_time, p.image as cover FROM posts p LEFT JOIN user_info ui ON p.author_id = ui.user_id WHERE p.status = 1
AND (p.title LIKE CONCAT('%', #{title}, '%'))
AND p.create_time >= #{startTime}
AND p.create_time <= #{endTime}
AND ui.user_name LIKE CONCAT('%', #{author}, '%')
UNION ALL
SELECT s.id as content_id, s.brief as title, 1 as type, s.author_id as author_id, ui.user_name as author_name, s.create_time as create_time, s.image as cover FROM share s LEFT JOIN user_info ui ON s.author_id = ui.user_id WHERE s.status = 1
AND (s.brief LIKE CONCAT('%', #{title}, '%'))
AND s.create_time >= #{startTime}
AND s.create_time <= #{endTime}
AND ui.user_name LIKE CONCAT('%', #{author}, '%')
) AS combined_results ORDER BY create_time DESC

SELECT s.id AS id, ui.user_id AS user_id, ui.user_name AS user_name, ui.image AS user_avatar, s.topic_id AS topic_id, s.brief AS brief, s.image AS image, s.create_time AS create_time, s.content_type AS content_type, IFNULL(browse_count.browse_count, 0) AS browse_count, IFNULL(like_count.like_count, 0) AS like_count FROM share s LEFT JOIN ( SELECT post_id, COUNT(*) AS browse_count FROM browse WHERE type = 1 GROUP BY post_id ) browse_count ON s.id = browse_count.post_id LEFT JOIN ( SELECT target_id AS post_id, COUNT(*) AS like_count FROM likes WHERE type = 1 AND status = 0 GROUP BY target_id ) like_count ON s.id = like_count.post_id LEFT JOIN user_info ui on ui.user_id = s.author_id WHERE
s.status = #{po.status}
s.status = 2
AND ui.user_name LIKE CONCAT('%', #{po.authorName}, '%')
AND s.create_time < #{po.endPublishTime}
AND s.create_time >= #{po.startPublishTime}
AND (s.brief LIKE CONCAT('%', #{po.title}, '%'))
AND s.topic_id = #{po.sort}
ORDER BY s.create_time DESC, s.id DESC

