select ui.user_id AS user_id, u.user_account as account, ui.user_name AS user_name, ui.sex as sex, ui.image AS image, u.phone as phone, u.email as email, u.status as status, ui.introduction AS introduction, ui.region AS region, ui.birth_date AS birthday, ui.profession AS profession, ui.is_vip AS vip, u.last_login_time AS last_login_time, u.create_time AS create_time, ui.update_time AS update_time from user_info ui right join user u on ui.user_id = u.id
u.status = #{po.status}
AND ui.user_name LIKE CONCAT('%', #{po.name}, '%')
AND u.user_account LIKE CONCAT('%', #{po.account}, '%')
AND u.email LIKE CONCAT('%', #{po.email}, '%')
AND u.phone LIKE CONCAT('%', #{po.phone}, '%')
AND u.create_time >= #{po.startTime}
AND u.create_time < #{po.endTime}
ORDER BY u.create_time DESC, u.id DESC

